@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;600;700;800;900&family=Roboto+Mono:wght@600;700;900&display=swap');
* { box-sizing: border-box; margin: 0; padding: 0; font-family: 'Inter', sans-serif; }
#kpi2-container {
  width: 100%;
  height: 100%;
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  align-items: stretch;
  gap: 12px;
  padding: 12px 10px;
  background: linear-gradient(135deg, #151a22 0%, #10141b 100%);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  overflow: visible;
}
.kpi2-card {
  --accent: #8b949e;
  --accent-soft: rgba(139, 148, 158, 0.12);
  position: relative;
  z-index: 1;
  min-width: 0;
  display: grid;
  grid-template-columns: 46px minmax(0, 1fr);
  align-items: center;
  gap: 14px;
  padding: 14px 16px;
  border-radius: 8px;
  background:
    linear-gradient(135deg, var(--accent-soft), rgba(255, 255, 255, 0.015) 42%),
    #11161d;
  border: 1px solid rgba(255, 255, 255, 0.09);
  box-shadow: inset 4px 0 0 var(--accent);
  overflow: visible;
}
.kpi2-card::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.06);
}
.kpi2-icon {
  width: 44px;
  height: 44px;
  display: grid;
  place-items: center;
  border-radius: 8px;
  color: var(--accent);
  background: var(--accent-soft);
  border: 1px solid color-mix(in srgb, var(--accent) 38%, transparent);
  font-size: 18px;
}
.kpi2-content {
  min-width: 0;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 5px;
}
.kpi2-label {
  font-size: 0.67rem;
  font-weight: 900;
  color: var(--accent);
  text-transform: uppercase;
  letter-spacing: 0;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi2-value {
  font-family: 'Roboto Mono', monospace;
  font-size: clamp(1.25rem, 2.35vw, 1.72rem);
  font-weight: 900;
  color: #ffffff;
  line-height: 1;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.kpi2-sub {
  font-size: 0.64rem;
  font-weight: 700;
  color: #8792a2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.c-eventos {
  --accent: #2ecc71;
  --accent-soft: rgba(46, 204, 113, 0.12);
}
.c-ips {
  --accent: #38bdf8;
  --accent-soft: rgba(56, 189, 248, 0.12);
}
.c-macs {
  --accent: #f59e0b;
  --accent-soft: rgba(245, 158, 11, 0.12);
}
.c-destinos {
  --accent: #a855f7;
  --accent-soft: rgba(168, 85, 247, 0.12);
}
@supports not (color: color-mix(in srgb, red 50%, transparent)) {
  .kpi2-icon { border-color: rgba(255, 255, 255, 0.16); }
}
@media (max-width: 1100px) {
  #kpi2-container {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
}
@media (max-width: 620px) {
  #kpi2-container {
    grid-template-columns: 1fr;
    overflow: auto;
  }
  .kpi2-card {
    min-height: 76px;
  }
}
.svg-icon{display:inline-grid;place-items:center;width:1em;height:1em;line-height:1;vertical-align:-.125em;flex-shrink:0}
.svg-icon svg{width:1em;height:1em;display:block}
.kpi2-info-btn{position:absolute;right:14px;top:50%;transform:translateY(-50%);width:30px;height:30px;border-radius:8px;border:1px solid rgba(255,255,255,.14);background:rgba(255,255,255,.07);color:#d7dde8;display:grid;place-items:center;font-size:14px;cursor:help;z-index:20}
.kpi2-info-btn:hover,.kpi2-info-btn:focus{background:var(--accent-soft);border-color:var(--accent);color:#fff;outline:none}
.kpi2-info-btn .svg-icon{font-size:14px}
.kpi2-tip{position:absolute;right:52px;top:50%;z-index:200;width:min(280px,calc(100vw - 32px));padding:10px 12px;border-radius:8px;background:rgba(15,22,33,.98);border:1px solid var(--accent);box-shadow:0 14px 34px rgba(0,0,0,.48);color:#d7dde8;font-size:11px;font-weight:700;line-height:1.45;opacity:0;transform:translate(8px,-50%);pointer-events:none;transition:opacity .15s ease,transform .15s ease}
.kpi2-tip strong{display:block;color:#fff;font-size:12px;margin-bottom:4px}
.kpi2-card:hover{z-index:30}
.kpi2-info-btn:hover+.kpi2-tip,.kpi2-info-btn:focus+.kpi2-tip{opacity:1;transform:translate(0,-50%)}
.kpi2-card{padding-right:58px}
@media (max-width:620px){#kpi2-container{overflow:visible}.kpi2-tip{right:52px;left:auto;width:min(260px,calc(100vw - 88px))}}

